mapper.select:
SELECT sl.*, u.user_name AS userName, c."id" AS customerId, c."name" AS customerName FROM t_sale_list sl LEFT JOIN t_user u ON sl.user_id = u.id LEFT JOIN t_customer c ON sl.customer_id = c."id"
AND sl.sale_number = #{saleListQuery.saleNumber}
AND sl.customer_id = #{saleListQuery.customerId}
AND sl.state = #{saleListQuery.state}
AND sl.sale_date >= TO_DATE(#{saleListQuery.startDate}, 'YYYY-MM-DD')
AND sl.sale_date <= TO_DATE(#{saleListQuery.endDate}, 'YYYY-MM-DD') + 1
ORDER BY sl.id DESC
